const { today } = await one(`select (now() at time zone 'Asia/Ho_Chi_Minh')::date::text today`);

// Test 1: Historical pause does not rewrite past owner day
await test('Historical pause does not rewrite past owner day (R02)', async () => {
  await db.exec(`
    insert into public.user_daily_tasks(user_id, task_date, carryover_version, carry_out_tests, finalized_at)
    values ('${owner}', date '${today}' - 2, 1, 8, now());
  `);
  const before = (await one(`select public.get_daily_task_status('${owner}', date '${today}' - 1) s`)).s;
  assert.equal(before.mode, 'owner');
  assert.equal(before.active_app_count, 1);

  // Pause today
  await db.exec(`update public.campaigns set status = 'paused', paused_reason = 'owner_manual' where id = '${camp1}'`);
  const after = (await one(`select public.get_daily_task_status('${owner}', date '${today}' - 1) s`)).s;

  assert.equal(after.mode, 'owner');
  assert.equal(after.active_app_count, 1);
  assert.equal(after.history_ready, true);
});

// Test 2: Lifecycle after day end (completed/deleted) preserves past owner day
await test('Campaign completion or deletion today preserves past owner day (R02)', async () => {
  await db.exec(`
    insert into public.user_daily_tasks(user_id, task_date, carryover_version, carry_out_tests, finalized_at)
    values ('${owner}', date '${today}' - 2, 1, 8, now());
  `);
  // Delete campaign today
  await db.exec(`delete from public.campaigns where id = '${camp1}'`);
  const afterDelete = (await one(`select public.get_daily_task_status('${owner}', date '${today}' - 1) s`)).s;
  assert.equal(afterDelete.mode, 'owner');
  assert.equal(afterDelete.active_app_count, 1);
  assert.equal(afterDelete.history_ready, true);
});

// Test 3: Disabled policy freezes debt and voluntary tests reduce it
await test('Disabled policy preserves debt and allows voluntary test reduction (R04)', async () => {
  await db.exec(`
    insert into public.user_daily_tasks(user_id, task_date, carryover_version, carry_out_tests, finalized_at)
    values ('${owner}', date '${today}' - 2, 1, 8, now());
    set test.allow_policy_retroactive_write = 'true';
    select public.set_daily_task_carryover_policy(date '${today}' - 1, false, 'disable policy');
    reset test.allow_policy_retroactive_write;
    select public.finalize_daily_tasks_for_date(date '${today}' - 1);
  `);
  const row = await one(`
    select carry_in_tests, carry_out_tests, finalized_at is not null sealed
    from public.user_daily_tasks where user_id = '${owner}' and task_date = date '${today}' - 1
  `);
  assert.equal(row.sealed, true);
  assert.equal(row.carry_in_tests, 8);
  assert.equal(row.carry_out_tests, 8);

  // Next day re-enabling policy restores the remaining 8 debt
  setSessionRole(owner);
  await db.exec(`
    set test.allow_policy_retroactive_write = 'true';
    select public.set_daily_task_carryover_policy(date '${today}', true, 're-enable policy');
    reset test.allow_policy_retroactive_write;
  `);
  const statusToday = (await one(`select public.get_daily_task_status('${owner}', date '${today}') s`)).s;
  assert.equal(statusToday.carry_in_tests, 8);
});

