import assert from 'node:assert/strict';
import { readdirSync } from 'node:fs';
import { createDb, read } from '../tools/baseline-lib.mjs';

const db = await createDb();
const owner = '11111111-1111-1111-1111-111111111111';
const other = '22222222-2222-2222-2222-222222222222';
const camp1 = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa';
const camp2 = 'bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb';
const req1 = 'cccccccc-cccc-cccc-cccc-cccccccccccc';
const req2 = 'dddddddd-dddd-dddd-dddd-dddddddddddd';

const one = async sql => (await db.query(sql)).rows[0];

async function test(name, fn) {
  await db.exec('begin');
  try {
    await fn();
    console.log(`PASS: ${name}`);
  } catch (e) {
    console.error(`FAIL: ${name}`, e);
    throw e;
  } finally {
    await db.exec('rollback');
  }
}

try {
  console.log('=== LOADING ACTIVE MIGRATIONS (062 THROUGH 066) ===');
  const migrationFiles = readdirSync(new URL('../../supabase/migrations/', import.meta.url))
    .filter(n => /^\d+.*\.sql$/.test(n))
    .sort();
  for (const name of migrationFiles) {
    await db.exec(read('supabase/migrations/' + name));
  }

  await db.exec(`
    insert into auth.users(id, email) values ('${owner}', 'owner@test.local'), ('${other}', 'other@test.local');
    update public.profiles set created_at = now() - interval '10 days', credits = 1000 where id in ('${owner}', '${other}');
    insert into public.campaigns(id, owner_id, app_name, package_name, status, slot_number, created_at)
    values ('${camp1}', '${owner}', 'OwnerApp', 'com.owner.app', 'open', 1, now() - interval '4 days');
    insert into public.campaigns(id, owner_id, app_name, package_name, status, slot_number, created_at)
    values ('${camp2}', '${other}', 'SupplyApp', 'com.supply.app', 'open', 1, now() - interval '4 days');
    delete from public.daily_task_carryover_policies;
    set test.allow_policy_retroactive_write = 'true';
    select public.set_daily_task_carryover_policy((now() at time zone 'Asia/Ho_Chi_Minh')::date - 6, true, 'seed');
    reset test.allow_policy_retroactive_write;
  `);

  const { today } = await one(`select (now() at time zone 'Asia/Ho_Chi_Minh')::date::text today`);

  // Test 1: Historical pause does not rewrite past owner day (safe deferral or exact preservation)
  await test('Historical pause does not rewrite past owner day (R02)', async () => {
    await db.exec(`
      insert into public.user_daily_tasks(user_id, task_date, carryover_version, carry_out_tests, finalized_at)
      values ('${owner}', date '${today}' - 2, 1, 8, now());
    `);
    const before = (await one(`select public.get_daily_task_status('${owner}', date '${today}' - 1) s`)).s;

    // Pause today
    await db.exec(`update public.campaigns set status = 'paused', paused_reason = 'owner_manual' where id = '${camp1}'`);
    const after = (await one(`select public.get_daily_task_status('${owner}', date '${today}' - 1) s`)).s;

    const passed = after.history_ready === false || (after.mode === before.mode && after.active_app_count === before.active_app_count);
    assert.ok(passed, 'Historical pause must defer unprovable history or preserve past owner count');
  });

  // Test 2: Deleting a campaign does not erase yesterday qualifying test count (D)
  await test('Deleted campaign preserves proven completed tests D (R02/D)', async () => {
    await db.exec(`
      insert into public.checkins(user_id, campaign_id, checkin_date, created_at)
      values ('${owner}', '${camp2}', date '${today}' - 1, now() - interval '1 day');
    `);
    const before = (await one(`select public.get_daily_task_status('${owner}', date '${today}' - 1) s`)).s;
    assert.equal(before.completed_tests, 1);

    // Delete supply campaign today
    await db.exec(`delete from public.campaigns where id = '${camp2}'`);
    const after = (await one(`select public.get_daily_task_status('${owner}', date '${today}' - 1) s`)).s;

    assert.equal(after.completed_tests, 1, 'Completed test count D must remain preserved in audit journal');
  });

  // Test 3: Disabled policy freezes debt and preserves carry_out = 8
  await test('Disabled policy preserves debt and allows voluntary test reduction (R04)', async () => {
    await db.exec(`
      insert into public.user_daily_tasks(user_id, task_date, carryover_version, carry_out_tests, finalized_at)
      values ('${owner}', date '${today}' - 2, 1, 8, now());
      set test.allow_policy_retroactive_write = 'true';
      select public.set_daily_task_carryover_policy(date '${today}' - 1, false, 'disable policy');
      reset test.allow_policy_retroactive_write;
      select public.finalize_daily_tasks_for_date(date '${today}' - 1);
    `);
    const row = await one(`
      select carry_in_tests, carry_out_tests, finalized_at is not null sealed
      from public.user_daily_tasks where user_id = '${owner}' and task_date = date '${today}' - 1
    `);
    assert.equal(row.sealed, true);
    assert.equal(row.carry_in_tests, 8);
    assert.equal(row.carry_out_tests, 8);

    // Re-enabling policy on today restores the remaining 8 debt
    await db.exec(`
      set test.allow_policy_retroactive_write = 'true';
      select public.set_daily_task_carryover_policy(date '${today}', true, 're-enable policy');
      reset test.allow_policy_retroactive_write;
    `);
    const statusToday = (await one(`select public.get_daily_task_status('${owner}', date '${today}') s`)).s;
    assert.equal(statusToday.carry_in_tests, 8);
  });

  // Test 4: Retroactive policy scheduling and past row moving rejected
  await test('Retroactive policy scheduling and past-row moving rejected (R04)', async () => {
    let rejected1 = false;
    try {
      await db.exec(`select public.set_daily_task_carryover_policy(date '${today}' - 2, false, 'retroactive')`);
    } catch (e) {
      rejected1 = true;
      assert.match(e.message, /CANNOT_MODIFY_HISTORICAL_POLICY/);
    }
    assert.ok(rejected1, 'Must reject retroactive scheduling');

    // Attempting to move past row to future date
    await db.exec(`
      set test.allow_policy_retroactive_write = 'true';
      insert into public.daily_task_carryover_policies(effective_from, is_enabled, operator_note)
      values (date '${today}' - 50, false, 'past policy') on conflict do nothing;
      reset test.allow_policy_retroactive_write;
    `);

    let rejected2 = false;
    try {
      await db.exec(`update public.daily_task_carryover_policies set effective_from = date '${today}' + 50 where effective_from = date '${today}' - 50`);
    } catch (e) {
      rejected2 = true;
      assert.match(e.message, /CANNOT_MODIFY_HISTORICAL_POLICY/);
    }
    assert.ok(rejected2, 'Must reject moving past policy to future date');
  });

  // Test 5: Reconcile push receipt RPC works for existing, paused, deleted, and non-existent requests
  await test('Reconcile push receipt RPC (R06/R08)', async () => {
    await db.exec(`set "request.jwt.claim.sub" = '${owner}'; set role authenticated;`);

    // Purchase push via push_campaign
    const purchaseResult = (await one(`select public.push_campaign('${camp1}', '${req1}') r`)).r;
    assert.equal(purchaseResult.success, true);
    assert.equal(purchaseResult.replayed, false);
    assert.equal(purchaseResult.balance_after, 900);

    // 1. Reconcile existing receipt (read-only, no extra deduction)
    const recon1 = (await one(`select public.reconcile_campaign_push_receipt('${camp1}', '${req1}') r`)).r;
    assert.equal(recon1.success, true);
    assert.equal(recon1.found, true);
    assert.equal(recon1.replayed, true);
    assert.equal(recon1.current_credits, 900);
    assert.equal(recon1.balance_after, 900);

    // 2. Reconcile when campaign is paused
    await db.exec(`reset role; update public.campaigns set status = 'paused', paused_reason = 'owner_manual' where id = '${camp1}'; set role authenticated;`);
    const reconPaused = (await one(`select public.reconcile_campaign_push_receipt('${camp1}', '${req1}') r`)).r;
    assert.equal(reconPaused.found, true);

    // 3. Reconcile when campaign is deleted
    await db.exec(`reset role; delete from public.campaigns where id = '${camp1}'; set role authenticated;`);
    const reconDeleted = (await one(`select public.reconcile_campaign_push_receipt('${camp1}', '${req1}') r`)).r;
    assert.equal(reconDeleted.found, true);
    assert.equal(reconDeleted.campaign_id, camp1);

    // 4. Reconcile non-existent request: returns found = false without purchasing or charging
    const reconNone = (await one(`select public.reconcile_campaign_push_receipt('${camp1}', '${req2}') r`)).r;
    assert.equal(reconNone.success, true);
    assert.equal(reconNone.found, false);

    // Verify credits were NOT deducted by reconcile
    await db.exec('reset role;');
    const p = await one(`select credits from public.profiles where id = '${owner}'`);
    assert.equal(p.credits, 900);
  });

  // Test 6: Finalizer refuses missing proof or pending source
  await test('Finalizer refuses missing proof or pending source (R01/R02)', async () => {
    // Attempting to finalize date without ready carryover source
    await db.exec(`select public.finalize_daily_tasks_for_date(date '${today}' - 1)`);
    const row = await one(`select finalized_at from public.user_daily_tasks where user_id = '${owner}' and task_date = date '${today}' - 1`);
    const p = await one(`select credits from public.profiles where id = '${owner}'`);
    assert.equal(row, undefined, 'Must not finalize or seal without proven/ready source');
    assert.equal(p.credits, 1000, 'Must not penalize');
  });

  console.log('=== ALL BASELINE 062+ REGRESSION TESTS PASSED ===');
} finally {
  await db.close();
}

